#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>

int main() {
  void *addr = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
  if (addr == MAP_FAILED) {
    perror("mmap failed");
    exit(1);
  }
  printf("Allocated virtual address: %p\n", addr);
  *((int *)addr) = 1234; //Write to virtual address
  printf("Value written: %d\n", *((int *)addr));
  if (munmap(addr, 4096) == -1) {
    perror("munmap failed");
    exit(1);
  }
  return 0;
}
